import {projects,services} from "./assets/content.js";
const $=(s)=>document.querySelector(s),icon=(name)=>`<svg aria-hidden="true"><use href="assets/icons.svg#${name}"/></svg>`;
function ProjectCard(p){return `<article class="project-card" data-category="${p.category}"><a href="work/${p.slug}/index.html"><figure><img src="assets/${p.slug}.webp" srcset="assets/${p.slug}-small.webp 720w, assets/${p.slug}.webp 1440w" sizes="(max-width:600px) 90vw, 46vw" width="1440" height="1080" alt="${p.alt}" ${p.slug==="common-ground"?'fetchpriority="high"':'loading="lazy"'}><span class="project-arrow">${icon("arrow")}</span></figure><div class="meta"><h3>${p.name}</h3><span>${p.category} / ${p.year}</span></div><span class="label">${p.client} · Concept</span><p>${p.line}</p></a></article>`;}
function ServicesGrid(){return services.map(s=>`<details class="service"><summary><h3>${s.name}</h3>${icon("plus")}</summary><div class="service-body"><div><p>${s.fit}</p><h4>Typical deliverables</h4><p>${s.deliverables}</p></div><div><h4>How we work</h4><p>${s.shape}</p><a class="text-link" href="#contact" data-service="${s.name}">Discuss ${s.name.toLowerCase()} ${icon("arrow")}</a></div></div></details>`).join("");}
if($("#project-grid"))$("#project-grid").innerHTML=projects.map(ProjectCard).join("");
if($("#services-grid"))$("#services-grid").innerHTML=ServicesGrid();
for(const button of document.querySelectorAll("[data-filter]"))button.addEventListener("click",()=>{const category=button.dataset.filter;for(const b of document.querySelectorAll("[data-filter]"))b.setAttribute("aria-pressed",String(b===button));let count=0;for(const card of document.querySelectorAll(".project-card")){card.hidden=category!=="All"&&card.dataset.category!==category;if(!card.hidden)count++;}$("#filter-status").textContent=`${count} ${category==="All"?"total":category.toLowerCase()} projects shown.`;});
const menu=$(".menu"),nav=$("#navigation");
menu?.addEventListener("click",()=>{const open=menu.getAttribute("aria-expanded")!=="true";menu.setAttribute("aria-expanded",String(open));menu.setAttribute("aria-label",open?"Close menu":"Open menu");nav.dataset.open=String(open);});
nav?.addEventListener("click",e=>{if(e.target.closest("a"))closeMenu(false);});
function closeMenu(focus=true){if(menu?.getAttribute("aria-expanded")==="true"){menu.setAttribute("aria-expanded","false");menu.setAttribute("aria-label","Open menu");nav.dataset.open="false";if(focus)menu.focus();}}
document.addEventListener("keydown",e=>{if(e.key==="Escape")closeMenu();});
const form=$("#inquiry"),status=$("#form-status"),receipt=$("#receipt");
document.querySelectorAll("[data-service]").forEach(a=>a.addEventListener("click",()=>{form.elements.type.value=a.dataset.service;form.elements.type.focus({preventScroll:true});}));
form?.addEventListener("submit",async e=>{e.preventDefault();receipt.hidden=true;for(const el of [form.elements.name,form.elements.summary]){el.setCustomValidity(el.value.trim().length<(el.name==="summary"?20:1)?"Please provide a meaningful value.":"");}if(!form.reportValidity())return;const button=form.querySelector("[type=submit]");button.disabled=true;button.setAttribute("aria-busy","true");status.textContent="Preparing your private preview…";try{await new Promise(r=>setTimeout(r,300));const values=new FormData(form),lines=[["Name","name"],["Email","email"],["Company","company"],["Website","website"],["Project","type"],["Timeline","timeline"],["Budget","budget"],["Found via","source"],["Summary","summary"]].map(([label,key])=>`${label}: ${String(values.get(key)||"Not provided").trim()}`);$("#receipt-text").textContent=lines.join("\n");receipt.hidden=false;status.textContent="Preview ready. Nothing has been sent or saved.";receipt.scrollIntoView({block:"nearest",behavior:matchMedia("(prefers-reduced-motion: reduce)").matches?"instant":"smooth"});}catch{status.textContent="Could not prepare the preview. Your draft is still here; try again.";}finally{button.disabled=false;button.removeAttribute("aria-busy");}});
form?.addEventListener("input",e=>{e.target.setCustomValidity?.("");if(!receipt.hidden){receipt.hidden=true;$("#receipt-text").textContent="";status.textContent="Draft changed. Preview again to review the updated details.";}});
$("#clear-inquiry")?.addEventListener("click",()=>{form.reset();receipt.hidden=true;$("#receipt-text").textContent="";status.textContent="Private draft cleared.";form.elements.name.focus();});
